// DeleteUniqueIndexCache 删除索引存在的缓存
func (w *WxXcxQrcodeRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.WxXcxQrcode) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, w.cache.Key(CacheWxXcxQrcodeByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[w.cache.Key(CacheWxXcxQrcodeByIDPrefix, item.ID)] = struct{}{}
			KeyMap[w.cache.Key(CacheWxXcxQrcodeByPageScenePrefix, item.Page, item.Scene)] = struct{}{}
			KeyMap[w.cache.Key(CacheWxXcxQrcodeByTokenPrefix, item.Token)] = struct{}{}
			KeyMap[w.cache.Key(CacheWxXcxQrcodeByPagePrefix, item.Page)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := w.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
